//! Valkey (BSD-licensed Redis fork): config file and supervisor spec.
//! Listens on 127.0.0.1 only, keeps RDB snapshots in its data dir.

use crate::store::{self, Instance};
use corral_core::fsutil::write_if_changed;
use corral_core::paths::Paths;
use corral_supervisor::Spec;
use std::path::Path;
use std::time::Duration;

fn q(p: &Path) -> String {
    format!("\"{}\"", p.display())
}

pub fn config(paths: &Paths, name: &str, inst: &Instance) -> String {
    format!(
        "# Generated by Corral. Changes are overwritten.\n\
         bind 127.0.0.1\n\
         protected-mode yes\n\
         port {port}\n\
         unixsocket {sock}\n\
         unixsocketperm 700\n\
         daemonize no\n\
         logfile \"\"\n\
         dir {dir}\n\
         dbfilename dump.rdb\n\
         save 3600 1 300 100 60 10000\n\
         appendonly no\n\
         databases 16\n{auth}",
        port = inst.port,
        sock = q(&store::socket(paths, name)),
        dir = q(&store::data_dir(paths, name)),
        auth = crate::auth::password(paths, name)
            .map(|pw| format!("requirepass \"{pw}\"\n"))
            .unwrap_or_default(),
    )
}

pub fn write_config(paths: &Paths, name: &str, inst: &Instance) -> std::io::Result<bool> {
    let file = store::conf_file(paths, name);
    let changed = write_if_changed(&file, config(paths, name, inst).as_bytes())?;
    crate::auth::make_private(&file)?;
    Ok(changed)
}

pub fn prepare(paths: &Paths, name: &str, inst: &Instance) -> anyhow::Result<()> {
    std::fs::create_dir_all(store::data_dir(paths, name))?;
    std::fs::create_dir_all(paths.run_dir())?;
    write_config(paths, name, inst)?;
    Ok(())
}

pub fn spec(paths: &Paths, name: &str, inst: &Instance) -> Spec {
    let dist = store::dist_dir(paths, inst.kind, &inst.version);
    let mut s = Spec::new(
        store::unit(name),
        dist.join("bin/valkey-server"),
        store::log_file(paths, name),
    )
    .args([store::conf_file(paths, name).display().to_string()]);
    // Saving the RDB snapshot on shutdown can take a moment.
    s.stop_timeout = Duration::from_secs(30);
    s
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::manifest::Kind;

    #[test]
    fn config_is_local_only() {
        let p = Paths::at("/Users/me/Library/Application Support/Corral");
        let inst = Instance {
            kind: Kind::Valkey,
            version: "9.1.3".into(),
            port: 6380,
            enabled: true,
        };
        let c = config(&p, "valkey", &inst);
        assert!(c.contains("bind 127.0.0.1\n"));
        assert!(c.contains("port 6380\n"));
        assert!(c.contains("protected-mode yes"));
        assert!(
            c.contains("dir \"/Users/me/Library/Application Support/Corral/services/data/valkey\"")
        );
        let s = spec(&p, "valkey", &inst);
        assert!(
            s.program
                .ends_with("services/dist/valkey-9.1.3/bin/valkey-server")
        );
    }
}
